from __future__ import annotations

from fastapi import APIRouter
from fastapi.responses import HTMLResponse

router = APIRouter(tags=["dashboard"])


@router.get("/dashboard", response_class=HTMLResponse)
def dashboard_view() -> HTMLResponse:
    return HTMLResponse(DASHBOARD_HTML.replace(
        "</body>", '<script src="/ui/preferences.js"></script></body>'))


DASHBOARD_HTML = r'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>ATLAS ULTIMATE — Trading Intelligence</title>
<meta name="description" content="ATLAS ULTIMATE unified market intelligence dashboard with MT5 telemetry, opportunity analysis, market context and financial news.">
<style>
:root{color-scheme:dark;--bg:#06080d;--panel:#0c121b;--card:#101722;--card2:#151d29;--line:#2a3545;--text:#f4efe6;--muted:#9ca7b5;--orange:#ff7a1a;--silver:#bcc5d0;--off:#f4efe6;--green:#39d98a;--red:#ff6174;--yellow:#f6c85f;--shadow:0 24px 70px #0008}*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;min-height:100vh;background:#06080d;color:var(--text);font:14px Inter,system-ui,-apple-system,Segoe UI,sans-serif;overflow-x:hidden}body:before{content:"";position:fixed;inset:0;z-index:-3;background:radial-gradient(circle at 12% 4%,#ff7a1a20 0,transparent 31%),radial-gradient(circle at 86% 12%,#60779b20 0,transparent 30%),linear-gradient(145deg,#05070b 0%,#0a1018 48%,#05070b 100%)}body:after{content:"";position:fixed;inset:0;z-index:-2;opacity:.23;background-image:linear-gradient(#7b87960d 1px,transparent 1px),linear-gradient(90deg,#7b87960d 1px,transparent 1px);background-size:42px 42px;mask-image:linear-gradient(to bottom,#000,transparent 78%)}.orb{position:fixed;z-index:-1;border:1px solid #ff7a1a28;border-radius:50%;filter:drop-shadow(0 0 18px #ff7a1a20)}.orb.one{width:430px;height:430px;right:-210px;top:90px}.orb.two{width:250px;height:250px;left:-110px;bottom:70px}.shell{max-width:1560px;margin:auto;padding:0 22px 28px}.hero{position:relative;margin:18px 0 20px;padding:26px 28px 30px;border:1px solid #344154;border-radius:26px;background:linear-gradient(135deg,#111925e8,#090d14f2);box-shadow:var(--shadow);overflow:hidden}.hero:after{content:"";position:absolute;width:420px;height:420px;right:-120px;top:-210px;border-radius:50%;background:radial-gradient(circle,#ff7a1a2b,transparent 68%)}.top{position:relative;z-index:2;display:flex;justify-content:space-between;align-items:center;gap:18px}.brand{display:flex;gap:15px;align-items:center}.logo{width:62px;height:62px;border:1px solid #ff8a24;border-radius:50%;display:grid;place-items:center;font-size:24px;font-weight:950;color:var(--orange);background:radial-gradient(circle at 35% 25%,#272f3a,#080b10 68%);box-shadow:inset 0 0 0 5px #ffffff05,0 0 26px #ff7a1a30}.title{font-size:29px;font-weight:950;letter-spacing:.09em}.sub{margin-top:4px;color:var(--silver);font-size:12px;letter-spacing:.04em}.actions{display:flex;gap:9px;align-items:center;flex-wrap:wrap}.btn{display:inline-flex;align-items:center;justify-content:center;min-height:42px;color:#090b0f;background:linear-gradient(180deg,#ff932f,#ff7514);text-decoration:none;padding:10px 15px;border-radius:12px;font-weight:900;border:1px solid #ffab5d;box-shadow:0 8px 24px #ff7a1a2d}.btn.ghost{background:#ffffff08;color:var(--off);border-color:#465469;box-shadow:none}.badge{border:1px solid #3b485a;padding:9px 12px;border-radius:999px;font-weight:850;background:#0a1018cc}.hero-copy{position:relative;z-index:2;display:grid;grid-template-columns:1.25fr .75fr;gap:24px;margin-top:34px;align-items:end}.kicker{color:var(--orange);font-size:11px;font-weight:900;letter-spacing:.17em;text-transform:uppercase}.hero h1{font-size:clamp(38px,5vw,72px);line-height:.97;letter-spacing:-.045em;margin:9px 0 16px;max-width:950px}.hero h1 span{color:var(--orange)}.lead{max-width:780px;color:#c5ced9;font-size:16px;line-height:1.65;margin:0}.visual-board{min-height:190px;border:1px solid #354255;border-radius:22px;background:linear-gradient(160deg,#131c28,#090d14);padding:18px;display:grid;grid-template-columns:repeat(2,1fr);gap:10px;box-shadow:inset 0 1px #ffffff0d}.visual-chip{border:1px solid #344153;border-radius:16px;padding:14px;background:#ffffff04}.visual-chip strong{display:block;font-size:20px;margin-top:7px}.mini,.label{font-size:10px;color:var(--muted)}.label{text-transform:uppercase;letter-spacing:.13em}.section-title{display:flex;align-items:end;justify-content:space-between;gap:12px;margin:26px 2px 12px}.section-title h2{margin:3px 0 0;font-size:20px}.grid{display:grid;gap:12px}.stats{grid-template-columns:repeat(6,1fr)}.split{grid-template-columns:1.65fr 1fr}.card{background:linear-gradient(180deg,#111925e8,#0a0f17f2);border:1px solid var(--line);border-radius:19px;padding:17px;box-shadow:0 16px 42px #0005;backdrop-filter:blur(12px)}.card:hover{border-color:#48576c}.big{font-size:25px;font-weight:900;margin-top:7px}.green{color:var(--green)}.red{color:var(--red)}.yellow{color:var(--yellow)}.row{display:grid;grid-template-columns:1.2fr .8fr .7fr .7fr .65fr;gap:8px;padding:11px 0;border-bottom:1px solid var(--line);align-items:center}.market{display:grid;grid-template-columns:1.1fr .8fr .6fr .45fr;gap:8px;padding:10px 0;border-bottom:1px solid var(--line);align-items:center}.pos{display:grid;grid-template-columns:1fr .65fr .75fr .7fr;gap:8px;padding:10px 0;border-bottom:1px solid var(--line)}.tag{display:inline-block;border:1px solid #435166;border-radius:999px;padding:4px 8px;font-size:10px;background:#ffffff05}.empty{color:var(--muted);padding:12px 0}.notice{border-left:3px solid var(--orange);padding:12px 14px;background:#ff8a240b;border-radius:10px;color:#bdc7d3;margin-top:14px}.story{display:block;padding:11px 0;border-bottom:1px solid var(--line);color:var(--text);text-decoration:none;line-height:1.45}.story:hover{color:var(--orange)}footer{margin-top:25px;border-top:1px solid #303b4b;background:linear-gradient(180deg,#0b1018,#05070b);padding:34px 0 40px}.footer-inner{max-width:1560px;margin:auto;padding:0 22px;display:grid;grid-template-columns:1fr auto;gap:22px;align-items:end}.footer-brand{font-size:23px;font-weight:950;letter-spacing:.08em}.footer-meta{color:var(--muted);max-width:850px;line-height:1.6;margin-top:8px}.footer-tag{color:var(--orange);font-weight:900;letter-spacing:.12em;font-size:11px}@media(max-width:1180px){.stats{grid-template-columns:repeat(3,1fr)}.hero-copy{grid-template-columns:1fr}.split{grid-template-columns:1fr}}@media(max-width:760px){.shell{padding:0 12px 18px}.hero{padding:19px 16px 22px;border-radius:20px}.top{align-items:flex-start;flex-direction:column}.title{font-size:21px}.logo{width:54px;height:54px}.stats{grid-template-columns:1fr 1fr}.row,.pos,.market{grid-template-columns:1fr 1fr}.visual-board{grid-template-columns:1fr 1fr}.footer-inner{grid-template-columns:1fr}.hero h1{font-size:42px}}
</style></head><body><div class="orb one"></div><div class="orb two"></div><div class="shell">
<section class="hero"><div class="top"><div class="brand"><div class="logo">A</div><div><div class="title">ATLAS ULTIMATE</div><div class="sub">JUST AI · Unified Trading Intelligence</div></div></div><div class="actions"><a class="btn ghost" href="#markets">Markets</a><a class="btn" href="#plans">Reader plans</a><div class="badge" id="status">CONNECTING</div></div></div>
<div class="hero-copy"><div><div class="kicker">AI MARKET OBSERVATORY</div><h1>One intelligence layer.<br><span>Every market signal.</span></h1><p class="lead">Live read-only MT5 telemetry, multi-asset opportunity analysis, Wall Street context and financial headlines — consolidated into one ATLAS ULTIMATE command center.</p></div><div class="visual-board"><div class="visual-chip"><div class="label">Core</div><strong>MT5</strong><div class="mini">Live telemetry</div></div><div class="visual-chip"><div class="label">Engine</div><strong>AI</strong><div class="mini">Decision support</div></div><div class="visual-chip"><div class="label">Coverage</div><strong>Multi-Asset</strong><div class="mini">FX · Metals · Crypto</div></div><div class="visual-chip"><div class="label">Mode</div><strong>Read Only</strong><div class="mini">Execution isolated</div></div></div></div></section>
<div class="section-title"><div><div class="label">LIVE ACCOUNT TELEMETRY</div><h2>Trading cockpit</h2></div></div>
<div class="grid stats"><div class="card"><div class="label">Account Type</div><div class="big" id="accountType">—</div></div><div class="card"><div class="label">Equity</div><div class="big" id="equity">—</div></div><div class="card"><div class="label">Balance</div><div class="big" id="balance">—</div></div><div class="card"><div class="label">Floating P/L</div><div class="big" id="floating">—</div></div><div class="card"><div class="label">Open Positions</div><div class="big" id="openPositions">—</div></div><div class="card"><div class="label">Execution Gate</div><div class="big yellow" id="execution">—</div></div></div>
<div class="section-title" id="markets"><div><div class="label">ATLAS ANALYTICS</div><h2>Opportunity matrix & account state</h2></div></div>
<div class="grid split"><section class="card"><div class="label">ATLAS Opportunity Matrix</div><div id="signals"></div></section><section class="card"><div class="label">Verified Account</div><div id="account"></div><div class="label" style="margin-top:18px">Open Positions</div><div id="positions"></div></section></div>
<div class="section-title"><div><div class="label">GLOBAL CONTEXT</div><h2>Wall Street board & financial news</h2></div></div>
<div class="grid split"><section class="card"><div class="label">Wall Street Board · Context only</div><div id="marketBoard"></div></section><section class="card"><div class="label">Financial News · Context only</div><div id="headlines"></div></section></div>
<div class="notice" id="disclaimer">Read-only telemetry. Trading involves risk.</div></div>
<footer><div class="footer-inner"><div><div class="footer-tag">JUST AI · ATLAS</div><div class="footer-brand">ATLAS ULTIMATE</div><div class="footer-meta">Unified market intelligence interface. MT5 execution remains isolated from public subscriber access. Market information is decision-support context and does not guarantee outcomes.</div></div><div class="mini">AI is for everyone.</div></div></footer>
<script>
function el(id){return document.getElementById(id)}function esc(value){return String(value==null?"":value).replace(/[&<>'"]/g,function(c){return {"&":"&amp;","<":"&lt;",">":"&gt;","'":"&#39;",'"':"&quot;"}[c]})}function money(value,currency){if(value==null)return "PRIVATE";return Number(value).toLocaleString(undefined,{minimumFractionDigits:2,maximumFractionDigits:2})+(currency?" "+currency:"")}function tone(value){return Number(value)>=0?"green":"red"}
function signalRow(x){return '<div class="row"><div><b>'+esc(x.canonical_symbol||x.symbol)+'</b><div class="mini">'+esc(x.asset_class)+' · '+esc(x.symbol)+'</div></div><div><span class="tag">'+esc(x.decision.bias)+'</span><div class="mini">'+esc(x.decision.decision)+'</div></div><div><b>'+Number(x.decision.score||0).toFixed(1)+'</b><div class="mini">score</div></div><div><b>'+Number(x.quality.execution_confidence||0).toFixed(1)+'%</b><div class="mini">confidence</div></div><div><b>'+Number(x.opportunity_score||0).toFixed(0)+'</b><div class="mini">opportunity</div></div></div>'}
async function refresh(){try{var response=await fetch("/dashboard/atlas",{cache:"no-store"});if(!response.ok)throw Error("offline");var data=await response.json(),account=data.account||{};el("status").textContent=data.verified_live_account?"VERIFIED LIVE":"ONLINE";el("accountType").textContent=account.account_type||"—";el("accountType").className="big "+(account.account_type==="REAL"?"green":"yellow");el("equity").textContent=money(account.equity,account.currency);el("balance").textContent=money(account.balance,account.currency);el("floating").textContent=money(data.floating_position_pnl,account.currency);el("floating").className="big "+tone(data.floating_position_pnl);el("openPositions").textContent=data.open_positions||0;el("execution").textContent=data.services.execution_gate;el("account").innerHTML='<div class="pos"><span>'+esc(account.label)+'</span><b>'+esc(account.login)+'</b><span>'+esc(account.server)+'</span><b>1:'+esc(account.leverage||"—")+'</b></div>';el("signals").innerHTML=(data.symbols||[]).map(signalRow).join("")||'<div class="empty">No markets available.</div>';el("positions").innerHTML=(data.positions||[]).map(function(p){return '<div class="pos"><div><b>'+esc(p.symbol)+'</b><div class="mini">'+esc(p.direction)+'</div></div><div>'+p.volume+'</div><div>'+p.price_open+'</div><div class="'+tone(p.profit)+'"><b>'+Number(p.profit||0).toFixed(2)+'</b></div></div>'}).join("")||'<div class="empty">No open positions.</div>';el("disclaimer").textContent=data.disclaimer}catch(error){el("status").textContent="OFFLINE"}}
async function refreshBriefing(){try{var response=await fetch("/dashboard/market-briefing",{cache:"no-store"});var data=await response.json();if(!response.ok)throw Error("unavailable");el("marketBoard").innerHTML=(data.market_board||[]).map(function(x){return '<div class="market"><div><b>'+esc(x.label)+'</b><div class="mini">'+esc(x.category)+'</div></div><b>'+(x.price==null?"—":Number(x.price).toLocaleString())+'</b><b class="'+tone(x.change_percent)+'">'+(x.change_percent==null?"—":Number(x.change_percent).toFixed(2)+"%")+'</b><span class="tag">'+esc(x.market_state)+'</span></div>'}).join("")||'<div class="empty">Market data temporarily unavailable.</div>';el("headlines").innerHTML=(data.headlines||[]).map(function(x){return '<a class="story" href="'+esc(x.url)+'" target="_blank" rel="noopener"><b>'+esc(x.title)+'</b><div class="mini">'+esc(x.source)+" · "+esc(x.published_at)+'</div></a>'}).join("")||'<div class="empty">Financial headlines temporarily unavailable.</div>'}catch(error){el("marketBoard").innerHTML='<div class="empty">Market board unavailable.</div>';el("headlines").innerHTML='<div class="empty">Headlines unavailable.</div>'}}
refresh();refreshBriefing();setInterval(refresh,5000);setInterval(refreshBriefing,60000);
</script></body></html>'''
